def backtrack_coloring(n):
    edges = [(i,j) for i in range(n) for j in range(i+1, n)]
    coloring = {}

    def is_valid_partial():
        # Check if any red K_4 is complete
        for quad in combinations(range(n), 4):
            edges_in_quad = list(combinations(quad, 2))
            if all((min(a,b), max(a,b)) in coloring and coloring[(min(a,b), max(a,b))] == 0 for a, b in edges_in_quad):
                return False
        # Check if any blue K_3 is complete
        for tri in combinations(range(n), 3):
            edges_in_tri = list(combinations(tri, 2))
            if all((min(a,b), max(a,b)) in coloring and coloring[(min(a,b), max(a,b))] == 1 for a, b in edges_in_tri):
                return False
        return True

    def backtrack(idx):
        if idx == len(edges):
            return True
        i, j = edges[idx]
        for c in [0, 1]:
            coloring[(i,j)] = c
            if is_valid_partial():
                if backtrack(idx + 1):
                    return True
            del coloring[(i,j)]
        return False

    if backtrack(0):
        return coloring
    return None

